+void TextEditorBase::_bind_methods() {
+	ClassDB::bind_method(D_METHOD("add_syntax_highlighter", "highlighter"), &TextEditorBase::add_syntax_highlighter);
+	ClassDB::bind_method(D_METHOD("get_base_editor"), &TextEditorBase::get_base_editor);
+}
