+	menu->clear();
+	for (EditorMenuItem item : item_list) {
+		switch (item.type) {
+			case SEPARATOR: {
+				menu->add_separator();
+				break;
+			}
+			case SHORTCUT: {
+				menu->add_shortcut(ED_GET_SHORTCUT(item.name), item.p_id);
+				break;
+			}
+			case ITEM: {
+				menu->add_item(TTRC(item.name), item.p_id);
+				break;
+			}
+			case SUBMENU_NODE_ITEM: {
+				menu->add_submenu_node_item(TTRC(item.name), item.node);
+				break;
+			}
+		}
+	}
