+Vector<TextEditorBase::EditorMenuItem> TextEditorBase::_make_context_menu(bool p_selection, bool p_foldable, Vector2 p_position, bool p_show) {
+	Vector<EditorMenuItem> item_list = {};
+	if (DisplayServer::get_singleton()->has_feature(DisplayServer::FEATURE_EMOJI_AND_SYMBOL_PICKER)) {
+		item_list.append(EditorMenuItem("Emoji & Symbols", EDIT_EMOJI_AND_SYMBOL, ITEM));
+		item_list.append(EditorMenuItem());
+	}
+	item_list.append(EditorMenuItem("ui_undo", EDIT_UNDO));
+	item_list.append(EditorMenuItem("ui_redo", EDIT_REDO));
+
+	item_list.append(EditorMenuItem());
+	item_list.append(EditorMenuItem("ui_cut", EDIT_CUT));
+	item_list.append(EditorMenuItem("ui_copy", EDIT_COPY));
+	item_list.append(EditorMenuItem("ui_paste", EDIT_PASTE));
+
+	item_list.append(EditorMenuItem());
+	item_list.append(EditorMenuItem("ui_text_select_all", EDIT_SELECT_ALL));
+
+	item_list.append(EditorMenuItem());
+	item_list.append(EditorMenuItem("script_text_editor/indent", EDIT_INDENT));
+	item_list.append(EditorMenuItem("script_text_editor/unindent", EDIT_UNINDENT));
+	item_list.append(EditorMenuItem("script_text_editor/toggle_bookmark", BOOKMARK_TOGGLE));
+
+	if (p_selection) {
+		item_list.append(EditorMenuItem());
+		item_list.append(EditorMenuItem("script_text_editor/convert_to_uppercase", EDIT_TO_UPPERCASE));
+		item_list.append(EditorMenuItem("script_text_editor/convert_to_lowercase", EDIT_TO_LOWERCASE));
+	}
+
+	if (p_foldable) {
+		item_list.append(EditorMenuItem("script_text_editor/toggle_fold_line", EDIT_TOGGLE_FOLD_LINE));
+	}
+
+	if (p_show) {
+		_build_menu(context_menu, item_list);
+		_show_context_menu(p_position);
+	}
+	return item_list;
+}
+
+void TextEditorBase::_show_context_menu(Vector2 p_position) {
+	const CodeEdit *tx = code_editor->get_text_editor();
+	context_menu->set_item_disabled(context_menu->get_item_index(EDIT_UNDO), !tx->has_undo());
+	context_menu->set_item_disabled(context_menu->get_item_index(EDIT_REDO), !tx->has_redo());
+
+	context_menu->set_position(get_screen_position() + p_position);
+	context_menu->reset_size();
+	context_menu->popup();
