+void TextEditorBase::_build_menu(PopupMenu *p_menu, Vector<EditorMenuItem> p_item_list) {
+	if (!p_menu) {
+		return;
+	}
+
+	p_menu->clear();
+	for (EditorMenuItem item : p_item_list) {
+		switch (item.type) {
+			case SEPARATOR: {
+				p_menu->add_separator();
+				break;
+			}
+			case SHORTCUT: {
+				p_menu->add_shortcut(ED_GET_SHORTCUT(item.name), item.p_id);
+				break;
+			}
+			case ITEM: {
+				p_menu->add_item(TTRC(item.name), item.p_id);
+				break;
+			}
+			case SUBMENU_NODE_ITEM: {
+				p_menu->add_submenu_node_item(TTRC(item.name), item.node);
+				break;
+			}
+		}
+	}
+}
