+bool TextEditorBase::is_unsaved() {
+	const bool unsaved =
+			code_editor->get_text_editor()->get_version() != code_editor->get_text_editor()->get_saved_version() ||
+			edited_res->get_path().is_empty(); // In memory.
+	return unsaved;
+}
