+		} break;
+		case EDIT_MOVE_LINE_DOWN: {
+			tx->move_lines_down();
+		} break;
+		case EDIT_INDENT: {
+			tx->indent_lines();
+		} break;
+		case EDIT_UNINDENT: {
+			tx->unindent_lines();
+		} break;
+		case EDIT_DELETE_LINE: {
+			tx->delete_lines();
+		} break;
+		case EDIT_DUPLICATE_SELECTION: {
+			tx->duplicate_selection();
+		} break;
+		case EDIT_DUPLICATE_LINES: {
