+void TextEditorBase::add_syntax_highlighter(Ref<EditorSyntaxHighlighter> p_highlighter) {
+	ERR_FAIL_COND(p_highlighter.is_null());
+
+	highlighters[p_highlighter->_get_name()] = p_highlighter;
+	highlighter_menu->add_radio_check_item(p_highlighter->_get_name());
+}
+
+void TextEditorBase::set_syntax_highlighter(Ref<EditorSyntaxHighlighter> p_highlighter) {
+	ERR_FAIL_COND(p_highlighter.is_null());
+
+	HashMap<String, Ref<EditorSyntaxHighlighter>>::Iterator el = highlighters.begin();
+	while (el) {
+		int highlighter_index = highlighter_menu->get_item_idx_from_text(el->key);
+		highlighter_menu->set_item_checked(highlighter_index, el->value == p_highlighter);
+		++el;
+	}
+
+	CodeEdit *te = code_editor->get_text_editor();
+	te->set_syntax_highlighter(p_highlighter);
+	p_highlighter->_set_edited_resource(edited_res);
+}
+
+void TextEditorBase::set_edited_resource(const Ref<Resource> &p_res) {
+	ERR_FAIL_COND(edited_res.is_valid());
+	ERR_FAIL_COND(p_res.is_null());
+
+	edited_res = p_res;
+
+	Ref<TextFile> text_file = edited_res;
+	String text;
+	if (text_file.is_valid()) {
+		text = text_file->get_text();
+	}
+
+	Ref<JSON> json_file = edited_res;
+	if (json_file.is_valid()) {
+		text = json_file->get_parsed_text();
+	}
+
+	code_editor->get_text_editor()->set_text(text);
+	code_editor->get_text_editor()->clear_undo_history();
+	code_editor->get_text_editor()->tag_saved_version();
+
+	emit_signal(SNAME("name_changed"));
+	code_editor->update_line_and_column();
+}
+
+bool TextEditorBase::is_unsaved() {
+	const bool unsaved =
+			code_editor->get_text_editor()->get_version() != code_editor->get_text_editor()->get_saved_version() ||
+			edited_res->get_path().is_empty(); // In memory.
+	return unsaved;
+}
+
+void TextEditorBase::tag_saved_version() {
+	code_editor->get_text_editor()->tag_saved_version();
+	ScriptEditorBase::tag_saved_version();
+}
+
+void TextEditorBase::reload_text() {
+	ERR_FAIL_COND(edited_res.is_null());
+
+	CodeEdit *te = code_editor->get_text_editor();
+	int column = te->get_caret_column();
+	int row = te->get_caret_line();
+	int h = te->get_h_scroll();
+	int v = te->get_v_scroll();
+
+	Ref<TextFile> text_file = edited_res;
+	if (text_file.is_valid()) {
+		te->set_text(text_file->get_text());
+	}
+
+	Ref<JSON> json_file = edited_res;
+	if (json_file.is_valid()) {
+		te->set_text(json_file->get_parsed_text());
+	}
+
+	Ref<Script> script = edited_res;
+	if (script.is_valid()) {
+		te->set_text(script->get_source_code());
+	}
+
+	te->set_caret_line(row);
+	te->set_caret_column(column);
+	te->set_h_scroll(h);
+	te->set_v_scroll(v);
+
+	te->tag_saved_version();
+
+	code_editor->update_line_and_column();
+	if (editor_enabled) {
+		_validate_script();
+	}
+}
+
+void TextEditorBase::enable_editor(Control *p_shortcut_context) {
+	if (editor_enabled) {
+		return;
+	}
+
+	editor_enabled = true;
+
+	_load_theme_settings();
+
+	_validate_script();
+
+	if (p_shortcut_context) {
+		for (int i = 0; i < edit_hb->get_child_count(); ++i) {
+			if (Control *c = cast_to<Control>(edit_hb->get_child(i))) {
+				c->set_shortcut_context(p_shortcut_context);
+			}
+		}
+	}
+}
